{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Restore the general regime: AUD 6m cap (25%)"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "AUD 5,000 de minimis, AUD 50,000 first-dollar basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "24-month claims period."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Separate fundamental/title claims: 100% cap, six-year minimum, outside basket, de minimis and knowledge bar."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Add a fraud, wilful concealment and deliberate misconduct carve-out from all caps, baskets, time limits, exclusive remedies and non-reliance."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Replace general disclosure with specific fair disclosure. Reject data room, public register and prudent-search deemed disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the buyer-knowledge exclusion or limit it to named Seller knowledge persons and reasonable enquiry, excluding title, capacity, fraud and specific indemnities."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "require effective consent and evidence of satisfied conditions before Completion. Reject consent-on-delivery and reasonable endeavours."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "require a current payout letter, direct repayment from Completion funds and effective releases."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "itemise the AUD 420,000 and on-costs in the funds flow, or make them seller-funded."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "broaden the IP indemnity and preserve the SOW3 cure. Verify the AUD 180,000 independently."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "require log preservation, investigation and regular updates. Make no breach or quantum assertions. Refer any remedy design to the principal."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "assess the three renewals. No automatic debt classification or price deduction."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Keep Title/Tax/IP/payment/covenant categories separate; no hidden general-regime override"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "obtain independent title, encumbrance and authority evidence. Do not rely on DD-012 alone."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax and IP: keep open. Reject settlement under the general regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

